sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-17: card number format, daily limit rules, one ACTIVE card per vehicle
    var last4 = (current.getValue('card_number_last4') || '').trim();
    if (!/^[0-9]{4}$/.test(last4)) {
        gs.addErrorMessage('Card Number Last 4 must be exactly 4 digits.');
        current.setAbortAction(true);
        return;
    }

    var status = current.getValue('status');
    if (status == 'LOST') {
        current.setValue('daily_limit', 0);
    } else if (status == 'ACTIVE' && !(parseFloat(current.getValue('daily_limit')) > 0)) {
        gs.addErrorMessage('Daily Limit must be greater than 0 for an ACTIVE card.');
        current.setAbortAction(true);
        return;
    }

    var vehicle = current.getValue('assigned_vehicle');
    if (vehicle && status == 'ACTIVE') {
        var other = new GlideRecord('x_1850693_enterp_0_fuel_card');
        other.addQuery('assigned_vehicle', vehicle);
        other.addQuery('status', 'ACTIVE');
        other.addQuery('sys_id', '!=', current.getUniqueValue());
        other.setLimit(1);
        other.query();
        if (other.next()) {
            gs.addErrorMessage('Vehicle ' + current.assigned_vehicle.getDisplayValue() + ' already has an ACTIVE fuel card (' + other.getValue('card_number_last4') + ').');
            current.setAbortAction(true);
        }
    }
})(current, previous);
